const pptxgen = require('pptxgenjs');

const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

const theme = {
  primary: "0B2545",    // Navy Blue
  secondary: "134074",  // Dark Blue
  accent: "8DA9C4",     // Steel Blue
  light: "EEF4ED",      // Off White/Light Gray
  bg: "FFFFFF"          // White
};

// Helper for page numbers
function addPageNumber(slide, number) {
  const numStr = String(number).padStart(2, '0');
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fill: { color: theme.accent },
    rectRadius: 0.15
  });
  slide.addText(numStr, {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });
}

// Slide 1: Cover Slide
const slide1 = pres.addSlide();
slide1.background = { color: theme.primary };
slide1.addText("Developer Workforce & Compensation Trends", {
  x: 0.5, y: 1.5, w: 9, h: 1.2,
  fontSize: 44, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center"
});
slide1.addText("2024 Stack Overflow Survey", {
  x: 0.5, y: 2.8, w: 9, h: 0.8,
  fontSize: 28, fontFace: "Arial", color: theme.accent, align: "center"
});
slide1.addText("65,437 respondents across 180+ countries\nSource: survey.stackoverflow.co/2024/work", {
  x: 0.5, y: 4.5, w: 9, h: 0.6,
  fontSize: 14, fontFace: "Arial", color: theme.light, align: "center"
});

// Slide 2: Employment Status Overview
const slide2 = pres.addSlide();
slide2.background = { color: theme.bg };
slide2.addText("84% of Developers Are Working, but Full-Time Employment Dips in the U.S.", {
  x: 0.5, y: 0.3, w: 9, h: 0.8,
  fontSize: 24, fontFace: "Arial", color: theme.primary, bold: true
});
addPageNumber(slide2, 2);

slide2.addText("Global Employment Breakdown:", { x: 0.5, y: 1.2, w: 4.5, h: 0.4, fontSize: 16, color: theme.secondary, bold: true });
slide2.addText("• Full-time: 69%\n• Freelance / Contractor: 16.4%\n• Student: 13.2%", {
  x: 0.5, y: 1.7, w: 4, h: 1.5, fontSize: 14, color: "333333", bullet: true
});

slide2.addText("U.S. Full-Time Trend:", { x: 5.0, y: 1.2, w: 4.5, h: 0.4, fontSize: 16, color: theme.secondary, bold: true });
slide2.addText("• 2023: 69%\n• 2024: 64.8%", {
  x: 5.0, y: 1.7, w: 4, h: 1.0, fontSize: 14, color: "333333", bullet: true
});

// Grouped bar chart for US vs Global full-time
const s2ChartData = [
  {
    name: "2023",
    labels: ["Global Full-time", "U.S. Full-time"],
    values: [69, 69]
  },
  {
    name: "2024",
    labels: ["Global Full-time", "U.S. Full-time"],
    values: [69, 64.8]
  }
];
slide2.addChart(pres.charts.BAR, s2ChartData, {
  x: 0.5, y: 2.5, w: 8.5, h: 2.5,
  barDir: "col",
  showLegend: true, legendPos: 'b',
  showTitle: false,
  showValue: true,
  chartColors: [theme.secondary, theme.accent]
});

// Slide 3: Work Environment Shift
const slide3 = pres.addSlide();
slide3.background = { color: theme.bg };
slide3.addText("In-Person Work Rises to 20% While Hybrid Holds Steady at 42%", {
  x: 0.5, y: 0.3, w: 9, h: 0.8,
  fontSize: 24, fontFace: "Arial", color: theme.primary, bold: true
});
addPageNumber(slide3, 3);

const s3ChartData = [
  {
    name: "In-Person",
    labels: ["2022", "2023", "2024"],
    values: [15, 16, 20]
  },
  {
    name: "Hybrid",
    labels: ["2022", "2023", "2024"],
    values: [0, 42, 42] // 0 for 2022/2023 as not strictly in brief, but we can just show 2024 or make a note. Brief says "consistent with 2023" for Hybrid. So 42 for 2023. Let's adjust.
  }
];
// Wait, the brief says: "Hybrid work remains the most common arrangement at 42%, consistent with 2023. Remote work accounts for 38%. In-person work has risen... 15% in 2022 to 16% in 2023 to 20% in 2024"
const s3ChartDataCorrected = [
  {
    name: "In-Person",
    labels: ["2022", "2023", "2024"],
    values: [15, 16, 20]
  },
  {
    name: "Hybrid",
    labels: ["2022", "2023", "2024"],
    values: [0, 42, 42]
  },
  {
    name: "Remote",
    labels: ["2022", "2023", "2024"],
    values: [0, 42, 38] // Inference for 2023 remote = 100-16-42 = 42. But we can just use 2024 data for hybrid/remote.
  }
];
// Actually, let's just make a simple bar chart of the 2024 breakdown, and a line/bar chart for the in-person trend.
slide3.addText("2024 Work Environment:", { x: 0.5, y: 1.2, w: 4, h: 0.4, fontSize: 16, color: theme.secondary, bold: true });
slide3.addChart(pres.charts.PIE, [
  {
    name: "Environment",
    labels: ["Hybrid", "Remote", "In-Person"],
    values: [42, 38, 20]
  }
], {
  x: 0.5, y: 1.7, w: 4, h: 3,
  showLegend: true, legendPos: 'b',
  showValue: true, showPercent: true,
  chartColors: [theme.secondary, theme.accent, theme.primary]
});

slide3.addText("In-Person Trend (2022-2024):", { x: 5.0, y: 1.2, w: 4, h: 0.4, fontSize: 16, color: theme.secondary, bold: true });
slide3.addChart(pres.charts.BAR, [
  {
    name: "In-Person %",
    labels: ["2022", "2023", "2024"],
    values: [15, 16, 20]
  }
], {
  x: 5.0, y: 1.7, w: 4, h: 3,
  barDir: "col",
  showValue: true,
  chartColors: [theme.primary]
});


// Slide 4: Salary by Developer Type
const slide4 = pres.addSlide();
slide4.background = { color: theme.bg };
slide4.addText("Senior Executives and Dev Advocates Top $124K+ Median Salary", {
  x: 0.5, y: 0.3, w: 9, h: 0.8,
  fontSize: 24, fontFace: "Arial", color: theme.primary, bold: true
});
addPageNumber(slide4, 4);

const s4ChartData = [
  {
    name: "Median Salary (USD)",
    labels: [
      "Senior Executive", "Dev Advocate", "Manager", "Dev Experience", 
      "SRE", "Cloud Infra.", "Blockchain", "Product Manager", 
      "Full-stack", "Front-end"
    ].reverse(),
    values: [
      127388, 124203, 115999, 109483, 
      99099, 96666, 85925, 80000, 
      63333, 48787
    ].reverse()
  }
];
slide4.addChart(pres.charts.BAR, s4ChartData, {
  x: 0.5, y: 1.3, w: 6.5, h: 3.8,
  barDir: "bar",
  showValue: true,
  valAxisMaxVal: 140000,
  chartColors: [theme.secondary]
});
slide4.addText("Reference: figure_1.jpg\nSRE and Cloud Infra. are highest-paid purely technical roles.", {
  x: 7.2, y: 2.0, w: 2.3, h: 1.5,
  fontSize: 12, color: "555555", italic: true
});

// Slide 5: Experience vs. Salary
const slide5 = pres.addSlide();
slide5.background = { color: theme.bg };
slide5.addText("Experience Pays: Top Roles Combine 14+ Years with Six-Figure Salaries", {
  x: 0.5, y: 0.3, w: 9, h: 0.8,
  fontSize: 22, fontFace: "Arial", color: theme.primary, bold: true
});
addPageNumber(slide5, 5);

// Scatter plot data requires X and Y values
const s5ChartData = [
  { name: "Senior Executive", values: [{ x: 17, y: 127388 }] },
  { name: "Dev Advocate", values: [{ x: 16, y: 124203 }] },
  { name: "Manager", values: [{ x: 15, y: 115999 }] },
  { name: "Dev Experience", values: [{ x: 12, y: 109483 }] },
  { name: "SRE", values: [{ x: 10, y: 99099 }] },
  { name: "Cloud Infra. Engineer", values: [{ x: 13, y: 96666 }] },
  { name: "Blockchain", values: [{ x: 9, y: 85925 }] },
  { name: "Product Manager", values: [{ x: 14, y: 80000 }] },
  { name: "Full-stack", values: [{ x: 10, y: 63333 }] },
  { name: "Front-end", values: [{ x: 8, y: 48787 }] },
  { name: "Student", values: [{ x: 2, y: 15466 }] }
];
slide5.addChart(pres.charts.SCATTER, s5ChartData, {
  x: 0.5, y: 1.3, w: 7.0, h: 3.8,
  lineSize: 0,
  showLegend: true, legendPos: 'r',
  valAxisTitle: "Median Salary (USD)",
  catAxisTitle: "Avg Years Experience",
  showTitle: false,
  chartColors: ["000000", "FF0000", "00FF00", "0000FF", "FFFF00", "00FFFF", "FF00FF", "800000", "008000", "000080", "808080"]
});
slide5.addText("Reference: figure_2.jpg", {
  x: 7.8, y: 4.8, w: 2.0, h: 0.5,
  fontSize: 10, color: "555555", italic: true
});

// Slide 6: Salary by Language
const slide6 = pres.addSlide();
slide6.background = { color: theme.bg };
slide6.addText("Erlang & Clojure Developers Earn >$95K; Dart & Prolog Below $45K", {
  x: 0.5, y: 0.3, w: 9, h: 0.8,
  fontSize: 22, fontFace: "Arial", color: theme.primary, bold: true
});
addPageNumber(slide6, 6);

const s6ChartData = [
  { name: "Erlang", values: [{ x: 12, y: 97000 }] },
  { name: "Clojure", values: [{ x: 11, y: 95000 }] },
  { name: "Elixir", values: [{ x: 11, y: 93000 }] },
  { name: "Perl", values: [{ x: 19, y: 90000 }] },
  { name: "Ruby", values: [{ x: 11, y: 89000 }] },
  { name: "Scala", values: [{ x: 9, y: 88000 }] },
  { name: "Go", values: [{ x: 9, y: 76000 }] },
  { name: "Python", values: [{ x: 9, y: 67000 }] },
  { name: "JavaScript", values: [{ x: 10, y: 64000 }] },
  { name: "PHP", values: [{ x: 10, y: 49000 }] },
  { name: "Dart", values: [{ x: 8, y: 44000 }] },
  { name: "Prolog", values: [{ x: 9, y: 43000 }] }
];
slide6.addChart(pres.charts.SCATTER, s6ChartData, {
  x: 0.5, y: 1.3, w: 7.0, h: 3.8,
  lineSize: 0,
  showLegend: true, legendPos: 'r',
  valAxisTitle: "Median Salary (USD)",
  catAxisTitle: "Avg Years Experience",
  showTitle: false,
  chartColors: ["000000", "FF0000", "00FF00", "0000FF", "FFFF00", "00FFFF", "FF00FF", "800000", "008000", "000080", "808080", "FFA500"]
});
slide6.addText("Note: Overall $10K drop in avg salary range vs 2023.\nReference: figure_3.jpg", {
  x: 7.8, y: 4.5, w: 2.0, h: 0.8,
  fontSize: 10, color: "555555", italic: true
});

// Slide 7: Company Size & Purchasing
const slide7 = pres.addSlide();
slide7.background = { color: theme.bg };
slide7.addText("47% Work at Sub-100 Orgs; 62% Influence Tech Purchases", {
  x: 0.5, y: 0.3, w: 9, h: 0.8,
  fontSize: 24, fontFace: "Arial", color: theme.primary, bold: true
});
addPageNumber(slide7, 7);

const s7PieData = [
  {
    name: "Company Size",
    labels: ["<100 emp.", "100-999 emp.", "1000+ emp."],
    values: [46.6, 25.2, 26.2] // 6.1+10.4+8.9+21.2 = 46.6, 18.5+6.7 = 25.2, 11+3.8+11.4 = 26.2
  }
];
slide7.addChart(pres.charts.PIE, s7PieData, {
  x: 0.5, y: 1.5, w: 4, h: 3.5,
  showLegend: true, legendPos: 'b',
  showValue: true, showPercent: true,
  chartColors: [theme.secondary, theme.accent, theme.primary]
});

slide7.addText("Purchasing Influence & Behavior:", {
  x: 5.0, y: 1.5, w: 4.5, h: 0.4, fontSize: 18, color: theme.primary, bold: true
});
slide7.addText(
  "• 62% of respondents influence tech purchases\n" +
  "• Highest among Senior Execs (99%), Managers (87%), PMs (77%)\n" +
  "• 60% prefer a 'build-and-buy' approach\n" +
  "• Top evaluation methods:\n" +
  "   - Starting a free trial (75%)\n" +
  "   - Asking other developers (73%)", {
  x: 5.0, y: 2.0, w: 4.5, h: 2.5,
  fontSize: 16, color: "333333", bullet: false
});

// Slide 8: Key Takeaways
const slide8 = pres.addSlide();
slide8.background = { color: theme.primary };
slide8.addText("Takeaways: What These Trends Mean for Hiring & Retention", {
  x: 0.5, y: 0.5, w: 9, h: 1.0,
  fontSize: 28, fontFace: "Arial", color: "FFFFFF", bold: true
});
addPageNumber(slide8, 8);

slide8.addText(
  "• Full-time employment softening: Plan for more contractors as full-time drops (down to 64.8% in U.S.).\n\n" +
  "• In-person mandates growing: In-person up to 20%, but hybrid (42%) is still dominant.\n\n" +
  "• DevRel & SRE command premium pay: Specialized and leadership roles top $100K+.\n\n" +
  "• Niche languages pay more: Erlang, Clojure, Elixir correlate with higher salaries than JS/PHP.\n\n" +
  "• Developers influence purchasing: Engage individual contributors directly (62% influence).", {
  x: 0.8, y: 1.6, w: 8.4, h: 3.5,
  fontSize: 18, fontFace: "Arial", color: "FFFFFF", bullet: { type: 'bullet' }
});

pres.writeFile({ fileName: '/app/output/final_deck.pptx' }).then(fileName => {
  console.log('created file: ' + fileName);
});

